package net.ludovicoflaviano.bettersfp.command;
import net.ludovicoflaviano.bettersfp.data.SpawnerStore;import org.bukkit.*;import org.bukkit.command.*;import org.bukkit.entity.Player;import org.bukkit.inventory.ItemStack;import java.util.*;
public final class BetterCommand implements CommandExecutor,TabCompleter {private final SpawnerStore store;public BetterCommand(org.bukkit.plugin.java.JavaPlugin p,SpawnerStore s){store=s;}public boolean onCommand(CommandSender s,Command c,String l,String[] a){if(a.length==0){s.sendMessage("§bBetterSpawners-Fork §7| /bs give <mob> [amount], /bs clear, /bs info");return true;}if(!s.hasPermission("bettersf.admin")){s.sendMessage("§cNo permission.");return true;}if(a[0].equalsIgnoreCase("clear")){int n=store.all().size();store.all().clear();store.save();s.sendMessage("§aCleared "+n+" spawners.");return true;}if(a[0].equalsIgnoreCase("info")){s.sendMessage("§bActive spawners: §f"+store.all().size());return true;}if(a[0].equalsIgnoreCase("give")&&s instanceof Player p){String mob=a.length>1?a[1].toUpperCase():"ZOMBIE";int amount=a.length>2?Math.max(1,Integer.parseInt(a[2])):1;try{org.bukkit.entity.EntityType.valueOf(mob);}catch(Exception ex){p.sendMessage("§cUnknown mob.");return true;}p.getInventory().addItem(new ItemStack(Material.SPAWNER,Math.min(64,amount)));p.sendMessage("§aGiven spawners.");return true;}s.sendMessage("§7Use /bs give <mob> [amount], /bs clear, /bs info");return true;}public List<String> onTabComplete(CommandSender s,Command c,String a,String[] x){return x.length==1?List.of("give","clear","info"):List.of();}}
